export interface MigrationFile {
  file: string;
  sql: string;
}

/** Renders src/bundle.generated.ts. Pure, so a test can check the file is current. */
export function renderBundle(files: MigrationFile[]): string {
  const entries = files.map(({ file, sql }) => {
    const m = /^(\d{4})_(.+)\.sql$/.exec(file);
    if (!m) throw new Error(`Bad migration file name: ${file}`);
    return `  { version: ${Number(m[1])}, name: ${JSON.stringify(m[2])}, sql: ${JSON.stringify(sql)} },`;
  });
  return [
    "// Generated by packages/db/scripts/bundle.ts from migrations/*.sql. Do not edit by hand.",
    'import type { Migration } from "./migrations.ts";',
    "",
    "export const BUNDLED_MIGRATIONS: Migration[] = [",
    ...entries,
    "];",
    "",
  ].join("\n");
}
